//--------------------------------------------------------------------------//

void  sensor_disable( Sensor sensor  )
{
    sensor->status.is_disabled   = TRUE ; 
		
	npc_stop( sensor->npc_trg  );
	
	npc_stop( sensor->npc_warn );
}
//--------------------------------------------------------------------------//

void sensor_warning_disable( Sensor sensor )
{
	sensor->status.warning_na = TRUE ; 

	npc_stop( sensor->npc_warn );
}
//--------------------------------------------------------------------------//

void sensor_trigger_disable( Sensor sensor )
{
	sensor->status.trigger_na = TRUE ;
	
	npc_stop( sensor->npc_trg );
}
